kage_css:
body{margin:0}
.th-manga .pose{border:3px solid #111;box-shadow:5px 5px 0 #111;border-radius:4px;background:#fff}
.md-riffle{animation:md-riffle 1.1s ease-in-out infinite;transform-box:fill-box;transform-origin:50% 100%}
.md-riffle.b{animation-delay:-.35s}.md-riffle.c{animation-delay:-.7s}
@keyframes md-riffle{0%,100%{transform:rotate(-30deg)}50%{transform:rotate(30deg)}}
.md-fly{animation:md-fly 1.4s ease-in infinite;transform-box:fill-box}
@keyframes md-fly{0%,15%{transform:translate(0,0) rotate(0);opacity:1}100%{transform:translate(70px,-26px) rotate(260deg);opacity:0}}
.md-pop{animation:md-pop 1.2s cubic-bezier(.2,1.6,.3,1) infinite;transform-box:fill-box;transform-origin:center}
@keyframes md-pop{0%,10%{transform:scale(.4);opacity:0}25%,80%{transform:scale(1);opacity:1}100%{opacity:0}}
.md-shake{animation:md-shake .3s steps(2) infinite;transform-box:fill-box;transform-origin:50% 100%}
@keyframes md-shake{50%{transform:translate(2px,-1px) rotate(-1.5deg)}}
.md-drip{animation:md-drip 1.6s ease-in infinite;transform-box:fill-box}
@keyframes md-drip{0%{transform:translateY(0);opacity:1}100%{transform:translateY(16px);opacity:0}}

hoshi_css:
body{margin:0}
.th-train.sheet{background:linear-gradient(#0f2134,#12263A 40%,#162c42)}
.th-train .pose{background:linear-gradient(#173049,#0f2134);border:2px solid #2b3a44;box-shadow:inset 0 -6px 0 #0b1620}
.th-train .pose::before{content:"";position:absolute;left:0;right:0;top:0;height:6px;background:repeating-linear-gradient(90deg,#8FC93A 0 30px,#0b1620 30px 34px)}
.hd-riffle{animation:hd-riffle 1.1s ease-in-out infinite;transform-box:fill-box;transform-origin:50% 100%}
.hd-riffle.b{animation-delay:-.35s}.hd-riffle.c{animation-delay:-.7s}
@keyframes hd-riffle{0%,100%{transform:rotate(-28deg)}50%{transform:rotate(28deg)}}
.hd-punch{animation:hd-punch 1.2s ease-in-out infinite;transform-box:fill-box;transform-origin:0 50%}
@keyframes hd-punch{0%,40%,100%{transform:rotate(0)}50%{transform:rotate(-14deg)}}
.hd-dot{animation:hd-dot 1.2s ease-in infinite;transform-box:fill-box}
@keyframes hd-dot{0%,48%{opacity:0;transform:translate(0,0)}52%{opacity:1}100%{opacity:0;transform:translate(-10px,28px)}}
.hd-pop{animation:hd-pop 1.2s cubic-bezier(.2,1.6,.3,1) infinite;transform-box:fill-box;transform-origin:center}
@keyframes hd-pop{0%,10%{transform:scale(.4);opacity:0}25%,80%{transform:scale(1);opacity:1}100%{opacity:0}}
.hd-wave{animation:hd-wave 1s ease-out infinite;transform-box:fill-box;transform-origin:0 50%}
.hd-wave.b{animation-delay:-.33s}.hd-wave.c{animation-delay:-.66s}
@keyframes hd-wave{0%{opacity:0;transform:scale(.6)}30%{opacity:1}100%{opacity:0;transform:scale(1.3)}}
.hd-cap{animation:hd-cap 1.4s cubic-bezier(.3,1.5,.5,1) infinite;transform-box:fill-box;transform-origin:50% 100%}
@keyframes hd-cap{0%,30%,100%{transform:translateY(0) rotate(0)}50%{transform:translateY(-16px) rotate(-10deg)}70%{transform:translateY(0)}}
.hd-shake{animation:hd-shake .3s steps(2) infinite;transform-box:fill-box;transform-origin:50% 100%}
@keyframes hd-shake{50%{transform:translate(2px,-1px) rotate(-1.5deg)}}
.hd-hop{animation:hd-hop .9s cubic-bezier(.3,0,.5,1) infinite;transform-box:fill-box;transform-origin:50% 100%}
@keyframes hd-hop{0%,100%{transform:translateY(0) scaleY(1)}15%{transform:translateY(0) scaleY(.94)}45%{transform:translateY(-10px) scaleY(1.03)}}
.hd-leaf{animation:hd-leaf 2.4s ease-in-out infinite;transform-box:fill-box;transform-origin:50% 100%}
@keyframes hd-leaf{50%{transform:rotate(14deg)}}
.hd-tail{animation:hd-tail 1.8s ease-in-out infinite;transform-box:fill-box;transform-origin:10% 90%}
@keyframes hd-tail{50%{transform:rotate(16deg)}}
.hd-tick{animation:hd-tick 1s steps(1) infinite;transform-box:view-box;transform-origin:96px 104px}
@keyframes hd-tick{0%{transform:rotate(0)}25%{transform:rotate(90deg)}50%{transform:rotate(180deg)}75%{transform:rotate(270deg)}}
.hd-spark{animation:hd-spark 1.4s ease-in-out infinite;transform-box:fill-box;transform-origin:center}
.hd-spark.b{animation-delay:-.7s}
@keyframes hd-spark{0%,100%{transform:scale(0) rotate(0);opacity:0}50%{transform:scale(1) rotate(90deg);opacity:1}}
.notes{display:flex;gap:14px;font-size:13px;color:#A9BEC0}
.notes span{white-space:nowrap;padding:6px 12px;border-radius:6px;background:#0A0F14;font:400 18px 'VT323';color:#FFB23E;box-shadow:0 0 0 2px #2b3a44}

kit_css:
body{margin:0}
.th-ukiyo .pose{background:radial-gradient(120% 90% at 50% 30%,#FBF4E4,#EFE3C8 70%);border:1px solid #1E2A4A;border-radius:4px;box-shadow:inset 0 0 0 5px #EFE3C8,inset 0 0 0 6px #C9A23A,4px 4px 0 rgba(30,42,74,.18)}
.th-ukiyo .pose b{font-size:20px;color:#1E2A4A}
.th-ukiyo .pose small{color:#6B6450;font-size:13px}
.kd-tail{animation:kd-tail 2.4s ease-in-out infinite;transform-box:view-box;transform-origin:60px 112px}
.kd-tail.b{animation-delay:-.8s}.kd-tail.c{animation-delay:-1.6s}
@keyframes kd-tail{50%{transform:rotate(6deg)}}
.kd-fan{animation:kd-fan 1.2s ease-in-out infinite;transform-box:fill-box;transform-origin:50% 100%}
.kd-fan.b{animation-delay:-.4s}.kd-fan.c{animation-delay:-.8s}
@keyframes kd-fan{0%,100%{transform:rotate(-26deg)}50%{transform:rotate(26deg)}}
.kd-fly{animation:kd-fly 1.4s ease-in infinite;transform-box:fill-box}
@keyframes kd-fly{0%,15%{transform:translate(0,0) rotate(0);opacity:1}100%{transform:translate(64px,-30px) rotate(300deg);opacity:0}}
.kd-fire{animation:kd-fire 1.6s ease-in-out infinite;transform-box:fill-box;transform-origin:50% 100%}
.kd-fire.b{animation-delay:-.5s}.kd-fire.c{animation-delay:-1s}
@keyframes kd-fire{0%,100%{transform:translateY(0) scale(1);opacity:.9}50%{transform:translateY(-8px) scale(1.15);opacity:1}}
.kd-nine{animation:kd-nine 2s cubic-bezier(.3,1.5,.5,1) infinite;transform-box:view-box;transform-origin:60px 112px}
@keyframes kd-nine{0%,100%{transform:scale(.6) rotate(0);opacity:.6}35%,80%{transform:scale(1) rotate(0);opacity:1}}
.kd-shake{animation:kd-shake .3s steps(2) infinite;transform-box:fill-box;transform-origin:50% 100%}
@keyframes kd-shake{50%{transform:translate(2px,-1px) rotate(-1.5deg)}}
.kd-bow{animation:kd-bow 2.4s ease-in-out infinite;transform-box:view-box;transform-origin:60px 120px}
@keyframes kd-bow{0%,20%,100%{transform:rotate(0)}45%,70%{transform:rotate(-8deg) translateY(4px)}}
.kd-coin{animation:kd-coin 1.6s ease-in infinite;transform-box:fill-box}
.kd-coin.b{animation-delay:-.5s}.kd-coin.c{animation-delay:-1.1s}
@keyframes kd-coin{0%{transform:translateY(-30px) rotateY(0);opacity:0}20%{opacity:1}100%{transform:translateY(40px) rotateY(720deg);opacity:0}}
.kd-steam{animation:kd-steam 2.4s ease-out infinite;transform-box:fill-box;transform-origin:50% 100%}
.kd-steam.b{animation-delay:-1.2s}
@keyframes kd-steam{0%{transform:translateY(4px) scaleY(.6);opacity:0}30%{opacity:.8}100%{transform:translateY(-14px) scaleY(1.2);opacity:0}}
.kd-pop{animation:kd-pop 1.4s cubic-bezier(.2,1.6,.3,1) infinite;transform-box:fill-box;transform-origin:center}
@keyframes kd-pop{0%,10%{transform:scale(.4);opacity:0}25%,80%{transform:scale(1);opacity:1}100%{opacity:0}}
